      }
      for(const g of groups.values()){ const o = { on:g.on, choices:g.choices }; if(g.group){ o.group = g.group; const mm = minMax(g.node.link, g.node.node); if(mm.min) o.min = mm.min; if(mm.max != null) o.max = mm.max; } out.push(o); }
    };
