  }
  const condsOf = m => [].concat(m.conditions || [], ...((m.conditionGroups || []).map(g => [].concat(g.conditions || [], ...((g.conditionGroups || []).map(h => h.conditions || [])))))).concat(...((m.conditionGroups || []).map(g => (g.localConditionGroups || []).flatMap(x => x.conditions || []))));
